package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.jlinalg.singlecell.ScviGeneProjection;
import org.junit.jupiter.api.Test;
import static org.jlinalg.cli.ScviModelRequest.*;

class ScviModelRequestTest {
    private static CountNetwork count(){return new CountNetwork(128,10,5,.1,Likelihood.ZINB,Dispersion.GENE_BATCH,Latent.NORMAL,true,true,true,Norm.BOTH,Norm.NONE,true);}
    private static Training training(int epochs,double train,Double val,Warmup warmup){return new Training(epochs,train,val,true,24,55421,Optimizer.ADAM,.001,1e-6,.01,warmup,0,1,null);}
    private static Training training(){return training(4,.8,.2,new Warmup(WarmupUnit.EPOCHS,4));}
    private static InputReview review(ScviMatrix.Kind kind){return new InputReview(kind,"investigator-selected counts/Pearson layer","declared upstream preprocessing; no automatic normalization","reviewed gene IDs/HVG selection","all admitted cells; no inferred filtering","synthetic control; user must supply actual study provenance");}
    private static ScviCovariates.Spec metadata(ScviCovariates.Labels use){return new ScviCovariates.Spec("batch",List.of("site"),List.of("age"),use==ScviCovariates.Labels.NONE?null:"label",use==ScviCovariates.Labels.NONE?null:"Unlabeled",use,List.of(),ScviMatrix.Precision.EXACT_FLOAT32,16);}
    private static SysviNetwork sys(Prior prior){return new SysviNetwork(256,15,2,.1,prior,true,false,Variance.FEATURE,false);}
    @Test void exactReleasesNeverAliasLatestOrOtherHistoricalVersions(){assertEquals(Release.V1_0_3,Release.parse("1.0.3"));assertEquals(Release.V1_2_0,Release.parse("1.2.0"));assertEquals(Release.V1_3_0,Release.parse("1.3.0"));for(String s:List.of("latest","1.3","1.3.1","1.0.3 ","1.3.0+patched"))assertThrows(IllegalArgumentException.class,()->Release.parse(s));}
    @Test void fiveLayerTenDimensionalReferenceAndBalancedAnnotationStayExplicit(){var fit=new Fit(Release.V1_3_0,count(),training(),new Annotation(new InheritedClassifier(),training(20,.8,.2,new Warmup(WarmupUnit.EPOCHS,20)),100),review(ScviMatrix.Kind.RAW_COUNTS));assertEquals(Family.SCANVI,fit.family());fit.validateMetadata(metadata(ScviCovariates.Labels.REFERENCE));assertEquals(5,fit.network().kwargs().get("n_layers"));assertEquals(10,fit.network().kwargs().get("n_latent"));assertEquals(100,((Map<?,?>)fit.annotation().protocol().get("training_kwargs")).get("n_samples_per_label"));assertEquals(false,fit.protocol().get("model_analysis_completed"));}
    @Test void popvClassifierSettingsDoNotRewriteTheEncoder(){var encoder=new CountNetwork(128,20,3,.05,Likelihood.NB,Dispersion.GENE,Latent.NORMAL,true,true,true,Norm.NONE,Norm.BOTH,true);var a=new Annotation(new NeuralClassifier(128,3,.1),training(20,.8,.2,new Warmup(WarmupUnit.EPOCHS,20)),20);var f=new Fit(Release.V1_0_3,encoder,training(),a,review(ScviMatrix.Kind.RAW_COUNTS));assertEquals(.05,encoder.kwargs().get("dropout_rate"));assertEquals(.1,((Map<?,?>)a.classifier().kwargs().get("classifier_parameters")).get("dropout_rate"));assertEquals("1.0.3",f.protocol().get("release"));}
    @Test void countModelsNeverAcceptSignedExpressionOrPoissonAnnotation(){assertThrows(IllegalArgumentException.class,()->new Fit(Release.V1_3_0,count(),training(),null,review(ScviMatrix.Kind.SIGNED_EXPRESSION)));var p=new CountNetwork(128,10,2,.1,Likelihood.POISSON,Dispersion.GENE,Latent.NORMAL,true,false,true,Norm.BOTH,Norm.NONE,true);assertDoesNotThrow(()->new Fit(Release.V1_3_0,p,training(),null,review(ScviMatrix.Kind.RAW_COUNTS)));assertThrows(IllegalArgumentException.class,()->new Fit(Release.V1_3_0,p,training(),new Annotation(new InheritedClassifier(),training(),null),review(ScviMatrix.Kind.RAW_COUNTS)));}
    @Test void sysviRequiresSignedExpressionAndExplicitlyZeroWarmup(){var noWarmup=training(100,1.,null,new Warmup(WarmupUnit.NONE,0));var fit=new Fit(Release.V1_3_0,sys(new Vamp(5,List.of())),noWarmup,null,review(ScviMatrix.Kind.SIGNED_EXPRESSION));assertEquals(Family.SYSVI,fit.family());assertEquals("vamp",fit.network().kwargs().get("prior"));assertEquals(5,fit.network().kwargs().get("n_prior_components"));assertEquals(0,noWarmup.planKwargs().get("n_epochs_kl_warmup"));assertEquals(0,noWarmup.planKwargs().get("n_steps_kl_warmup"));assertThrows(IllegalArgumentException.class,()->new Fit(Release.V1_3_0,sys(new StandardNormal()),training(),null,review(ScviMatrix.Kind.SIGNED_EXPRESSION)));assertThrows(IllegalArgumentException.class,()->new Fit(Release.V1_2_0,sys(new StandardNormal()),noWarmup,null,review(ScviMatrix.Kind.SIGNED_EXPRESSION)));assertThrows(IllegalArgumentException.class,()->new Fit(Release.V1_3_0,sys(new StandardNormal()),noWarmup,null,review(ScviMatrix.Kind.RAW_COUNTS)));}
    @Test void explicitVampCellIndicesAreImmutableAndRetainRepeatedSourceIndices(){var source=new ArrayList<>(List.of(0,0,2));var prior=new Vamp(3,source);source.set(0,100);assertEquals(List.of(0,0,2),prior.pseudoinputCellIndices());sys(prior).validatePopulation(3);assertThrows(IllegalArgumentException.class,()->sys(prior).validatePopulation(2));assertThrows(IllegalArgumentException.class,()->new Vamp(3,List.of(0,1)));assertFalse(new Vamp(5,List.of()).kwargs().containsKey("pseudoinputs_data_indices"));assertFalse(new StandardNormal().kwargs().containsKey("n_prior_components"));}
    @Test void epochAndStepWarmupsCannotAccidentallyActivateTheOtherDefault(){var epochs=new Warmup(WarmupUnit.EPOCHS,20).kwargs();var steps=new Warmup(WarmupUnit.STEPS,1000).kwargs();assertEquals(20,epochs.get("n_epochs_kl_warmup"));assertNull(epochs.get("n_steps_kl_warmup"));assertNull(steps.get("n_epochs_kl_warmup"));assertEquals(1000,steps.get("n_steps_kl_warmup"));assertThrows(IllegalArgumentException.class,()->new Warmup(WarmupUnit.NONE,20));assertThrows(IllegalArgumentException.class,()->new Warmup(WarmupUnit.STEPS,0));}
    @Test void completeTrainingFractionsAndValidationStoppingAreChecked(){assertThrows(IllegalArgumentException.class,()->training(5,.9,.2,new Warmup(WarmupUnit.NONE,0)));assertThrows(IllegalArgumentException.class,()->training(5,Double.NaN,.2,new Warmup(WarmupUnit.NONE,0)));var stop=new EarlyStopping(StopMetric.RECONSTRUCTION_VALIDATION,Direction.MIN,0,0,1);assertThrows(IllegalArgumentException.class,()->new Training(100,1.,null,true,24,1,Optimizer.ADAM,.001,0,.01,new Warmup(WarmupUnit.NONE,0),0,1,stop));var train=new Training(100,.8,null,true,24,1,Optimizer.ADAM,.001,0,.01,new Warmup(WarmupUnit.NONE,0),0,1,stop);assertEquals("reconstruction_loss_validation",train.kwargs().get("early_stopping_monitor"));assertEquals(0,train.kwargs().get("early_stopping_patience"));}
    @Test void seedAndOptimizerParametersNeverTriggerUpstreamFallbacks(){assertThrows(IllegalArgumentException.class,()->new Training(1,1.,null,true,24,4_294_967_296L,Optimizer.ADAM,.001,0,.01,new Warmup(WarmupUnit.NONE,0),0,1,null));assertThrows(IllegalArgumentException.class,()->new Training(1,1.,null,true,24,1,Optimizer.ADAM,Double.NaN,0,.01,new Warmup(WarmupUnit.NONE,0),0,1,null));assertThrows(IllegalArgumentException.class,()->new Training(1,1.,null,true,24,1,Optimizer.ADAM,.001,-1,.01,new Warmup(WarmupUnit.NONE,0),0,1,null));assertThrows(IllegalArgumentException.class,()->new Training(1,1.,null,true,24,1,Optimizer.ADAM,.001,0,0,new Warmup(WarmupUnit.NONE,0),0,1,null));}
    @Test void unannotatedFitsAndGeneLabelModelsHaveDifferentLabelRoles(){var f=new Fit(Release.V1_3_0,count(),training(),null,review(ScviMatrix.Kind.RAW_COUNTS));f.validateMetadata(metadata(ScviCovariates.Labels.NONE));assertThrows(IllegalArgumentException.class,()->f.validateMetadata(metadata(ScviCovariates.Labels.REFERENCE)));var c=new CountNetwork(128,10,1,.1,Likelihood.NB,Dispersion.GENE_LABEL,Latent.NORMAL,true,false,true,Norm.BOTH,Norm.NONE,true);var labeled=new Fit(Release.V1_3_0,c,training(),null,review(ScviMatrix.Kind.RAW_COUNTS));labeled.validateMetadata(metadata(ScviCovariates.Labels.REFERENCE));assertThrows(IllegalArgumentException.class,()->labeled.validateMetadata(metadata(ScviCovariates.Labels.NONE)));}
    @Test void fixedQueriesRetainTheFittedFamilyAndRequireReferenceTrust(){var q=new Query(Release.V1_3_0,Family.SCANVI,ScviGeneProjection.Policy.PAD_MISSING_AND_DROP_EXTRA,new SelectiveFreeze(false,true,true,true,false,true),training(100,1.,null,new Warmup(WarmupUnit.EPOCHS,100)),review(ScviMatrix.Kind.RAW_COUNTS));assertEquals(true,q.protocol().get("reference_model_trust_required"));assertEquals(100,((Map<?,?>)q.protocol().get("training_kwargs")).get("max_epochs"));assertEquals(false,q.freeze().kwargs().get("freeze_dropout"));assertEquals(true,q.freeze().kwargs().get("freeze_classifier"));assertThrows(IllegalArgumentException.class,()->new Query(q.release(),q.referenceFamily(),ScviGeneProjection.Policy.SHARED_BEFORE_TRAINING,q.freeze(),q.training(),q.inputReview()));assertThrows(IllegalArgumentException.class,()->new Query(q.release(),Family.SYSVI,q.genePolicy(),q.freeze(),q.training(),q.inputReview()));}
    @Test void unfrozenRequestsHaveNoIgnoredSelectiveFreezeFlags(){assertEquals(Map.of("unfrozen",true),new Unfrozen().kwargs());assertEquals(Map.of("linear_classifier",true),new LinearClassifier().kwargs());assertEquals(Map.of(),new InheritedClassifier().kwargs());}
    @Test void protocolIsReadOnlyEscapedDataAndNeverACompletedAnalysis()throws Exception{var f=new Fit(Release.V1_3_0,count(),training(),null,review(ScviMatrix.Kind.RAW_COUNTS));assertThrows(UnsupportedOperationException.class,()->f.protocol().put("runtime_admission_required",false));assertThrows(UnsupportedOperationException.class,()->f.network().kwargs().put("n_layers",0));String json=RegenieRuntime.json(f.protocol());assertInstanceOf(Map.class,SimpleJson.parse(json));assertTrue(json.contains("declaration_does_not_prove_provenance"));assertTrue(json.contains("runtime_admission_required"));assertTrue(json.contains("\"model_analysis_completed\":false"));}
    @Test void expressionProvenanceCannotBeOmittedOrTurnedIntoAnUnboundedPayload(){assertThrows(IllegalArgumentException.class,()->new InputReview(ScviMatrix.Kind.RAW_COUNTS,"","none","all","all","reviewed"));assertThrows(IllegalArgumentException.class,()->new InputReview(ScviMatrix.Kind.SIGNED_EXPRESSION,"x","x","x","x","z".repeat(16385)));assertThrows(IllegalArgumentException.class,()->new CountNetwork(0,10,1,.1,Likelihood.NB,Dispersion.GENE,Latent.NORMAL,true,false,true,Norm.BOTH,Norm.NONE,true));assertThrows(IllegalArgumentException.class,()->new NeuralClassifier(128,3,Double.NaN));}
}
